+                double y = startY + i * dY;
+                points[i] = (((long) GeoEncodingUtils.encodeLongitude(x)) << 32) | GeoEncodingUtils.encodeLatitude(y) & 0xffffffffL;
+                values[i] = startValue + i * dV;
+            }
+            return new InternalGeoLine(
+                name,
+                points,
+                values,
+                Collections.emptyMap(),
+                randomBoolean(),
+                randomBoolean(),
+                sortOrder,
+                docs,
+                true,
+                simplified
+            );
+        }
+    }
